def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point(object):
        def __init__(self, *args, **kwargs):
            self.name = name
            self.fields = fields
            self.srid_map = srid_map

        def __repr__(self):
            return f"Point({self.name}, {self.fields}, {self.srid_map})"

        def __str__(self):
            return f"Point({self.name}, {self.fields}, {self.srid_map})"

        def __eq__(self, other):
            return (self.name == other.name and
                    self.fields == other.fields and
                    self.srid_map == other.srid_map)

        def __ne__(self, other):
            return not self.__eq__(other)

        def __hash__(self):
            return hash((self.name, self.fields, self.srid_map))

        def __getitem__(self, key):
            return self.fields[key]

        def __setitem__(self, key, value):
            self.fields[key] = value

        def __delitem__(self, key):
            del self.fields[key]

        def __iter__(self):
            return iter(self.fields)

        def __len__(self):
            return len(self.fields)

        def __contains__(self, key):
            return key in self.fields

        def __copy__(self):
            return Point(self.name, self.fields, self.srid_map)

        def __deepcopy__(self, memo):
            return Point(self.name, self.fields, self.srid_map)

        def __reduce__(self):
            return (Point, (self.name, self.fields, self.srid_map))

        def __reduce_ex__(self, protocol):
            return self.__reduce__()

        def __sizeof__(self):
            return sys.getsizeof(self.name) + sys.getsizeof(self.fields)

