def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2 or v != d2[k]:
                result[k] = v
            elif isinstance(v, dict):
                result[k] = difference(v, d2.get(k, {}), level - 1)
        return result

def fill(self, coord, weight=1):
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Coordinates must be a tuple of length 2")
    if not isinstance(weight, int) or weight < 0:
        raise ValueError("Weight must be a non-negative integer")

    x, y = coord
    if x < 0 or x >= self.width or y < 0 or y >= self.height:
        return

    self.histogram[x][y] += weight

    if self.histogram[x][y] > self.max_value:
        self.max_value = self.histogram[x][y]

    if self.histogram[x][y] < self.min_value:
        self.min_value = self.histogram[x][y]

    self.total_weight += weight

    if self.total_weight > self.max_total_weight:
        self.max_total_weight = self.total_weight

    if self.total_weight < self.min_total_weight:
        self.min_total_weight = self.total_weight

    self.num_points += 1

    if self.num_points > self.max_num_points:
        self.max_num_points = self.num_points

    if self.num_points < self.min_num_points:
        self.min_num_points = self.num_points

    self.mean = self.total_weight / self.num_points

    self.variance = (self.total_weight * self.total_weight - self.mean * self.mean) / (self.num_points - 1)

    self.standard_deviation = math.sqrt(self.variance)

    self.skewness = math.sqrt(self.num_points) * math.sqrt(self.variance)

    self.kurtosis = math.sqrt(self.num_points) * math.sqrt(self.variance)

    self.median = self.hist

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    # Check that all keys and values are strings or bytes-like objects
    for key, value in labels.items():
        if not isinstance(key, (str, bytes)) or not isinstance(value, (str, bytes)):
            raise ValidationError(
                f"Label key '{key}' or label value '{value}' is not a string or bytes-like object"
            )

    # Check that all keys match the regular expression
    for key in labels.keys():
        if not re.match(LABEL_KEY_REGEX, key):
            raise ValidationError(
                f"Label key '{key}' does not match the regex {LABEL_KEY_REGEX}"
            )

    # Check that all values match the regular expression
    for value in labels.values():
        if not re.match(LABEL_VALUE_REGEX, value):
            raise ValidationError

