def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is present
    if not fixity:
        raise ValueError("Fixity block is not present in the inventory")

    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dictionary")

    # Check if the fixity block has the correct keys
    expected_keys = ["files", "checksums"]
    if not all(key in fixity for key in expected_keys):
        raise ValueError("Fixity block is missing required keys")

    # Check if the files list is a list
    if not isinstance(fixity["files"], list):
        raise ValueError("Files list in fixity block is not a list")

    # Check if the checksums list is a list
    if not isinstance(fixity["checksums"], list):
        raise ValueError("Checksums list in fixity block is not a list")

    # Check if the number of files and checksums is the same
    if len(fixity["files"]) != len(fixity["checksums"]):
        raise ValueError("Number of files and checksums in fixity block is not the same")

    # Check if all files in the manifest are referenced in the fixity block
    for file in manifest_files:
        if file not in fixity["files"]:
            raise ValueError(f"File {file} is not referenced in the fixity block")

    # Check if all checksums in the fixity block are valid
    for checksum in fixity["checksums"]:
        if not isinstance(checksum, str) or not checksum.isalnum():
            raise ValueError("Checksum in fixity block is not a valid string")

    # If all checks pass, return True
    return True

