def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            left, right = arg.args
            if isinstance(left, Or) and left.args[0] == arg:
                new_args.append(left.args[1])
            elif isinstance(right, Or) and right.args[0] == arg:
                new_args.append(right.args[1])
            else:
                new_args.append(arg)
        elif isinstance(arg, Or):
            left, right = arg.args
            if isinstance(left, And) and left.args[0] == arg:
                new_args.append(left.args[1])
            elif isinstance(right, And) and right.args[0] == arg:
                new_args.append(right.args[1])
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

