def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        raise ValueError("No pieces to render")
    if style not in ("normal", "bold", "italic"):
        raise ValueError("Invalid style")

    # Render the pieces
    rendered_pieces = []
    for piece in pieces:
        if piece.startswith("**"):
            rendered_pieces.append(f"<b>{piece[2:]}</b>")
        elif piece.startswith("*"):
            rendered_pieces.append(f"<i>{piece[1:]}</i>")
        else:
            rendered_pieces.append(piece)

    # Join the rendered pieces
    rendered_text = "".join(rendered_pieces)

    # Apply the requested style
    if style == "normal":
        return rendered_text
    elif style == "bold":
        return f"<b>{rendered_text}</b>"
    elif style == "italic":
        return f"<i>{rendered_text}</i>"
    else:
        raise ValueError("Invalid style")

