        key, value = self.queue.pop(0)
        return key, value
    except IndexError:
        raise KeyError("popitem(): lru cache is empty")

def popitem(self):
    try:
        key = list(self.keys())[random.randint(0, len(self.keys()) - 1)]
        value = self[key]
        del self[key]
        return key, value
    except IndexError:
        raise KeyError("popitem(): dictionary is empty")

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    return re.compile(r"(?:^|[^\w])in\s*=\s*([^\s]+)")

