def default_tzinfo(dt, tzinfo):
    if dt.tzinfo is not None:
        return dt
    else:
        return dt.replace(tzinfo=tzinfo)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request.is_public_message():
        return "public_message"
    elif request.is_private_message():
        return "private_message"
    elif request.is_legacy_payload():
        return "legacy_payload"
    else:
        raise ValueError("Invalid request type")

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if request.method == "POST" and request.path.startswith("/_matrix"):
        return True
    else:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def find_tags(text, replacer=None):
    tags = set()
    original_text = text

    # Find tags inside code blocks
    in_code_block = False
    for i, char in enumerate(text):
        if char == '`':
            in_code_block = not in_code_block
        elif not in_code_block and char == '#':
            # Found a tag
            tag = text[i + 1:].split(' ')[0]
            tags.add(tag)
            if replacer is not None:
                original_text = original_text.replace(tag, replacer(tag))

    return tags, original_text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        if response.status_code == 200:
            return response.headers.get('Content-Type')
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    if tag.isalnum():
        return True
    if tag[0].isalpha() and tag[1:].isdigit():
        return True
    return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = node.getchildren()
    result = {}
    for child in children:
        if child.tag not in result:
            result[child.tag] = []
        result[child.tag].append(child.text)
    return result

