def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    # Validate input
    if not url:
        raise ValueError("Invalid URL")

    # Construct the NodeInfo document
    nodeinfo_document = {
        "software": "Diaspora",
        "version": "0.1.0",
        "protocols": [
            {
                "name": "activitypub",
                "version": "1.0"
            }
        ],
        "services": [
            {
                "type": "Inbound",
                "service": "activitypub",
                "base_url": url
            }
        ],
        "usage": {
            "users": 1000,
            "hosts": 10
        },
        "protocol_data": {
            "activitypub": {
                "inbound": {
                    "base_url": url
                }
            }
        }
    }

    # Add custom document path if supplied
    if document_path:
        nodeinfo_document["document_path"] = document_path

    return nodeinfo_document

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Verify the signature using the public key
        if not public_key.verify(signature, doc, padding.PKCS1v15(), hashes.SHA256()):
            raise ValueError("Invalid signature")
    except (ValueError, TypeError, AttributeError) as e:
        # Handle potential invalid inputs or runtime issues
        raise ValueError("Invalid input or signature") from e
    return True

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        response = requests.get(f"https://webfinger.net/{handle}/.well-known/webfinger")
        if response.status_code == 200:
            return response.text
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        response = requests.get(f"https://{handle}.diaspora.software/.well-known/webfinger")
        response.raise_for_status()
        data = response.json()
        return data
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 404:
            raise ValueError(f"Invalid handle: {handle}")
        else:
            raise e
    except requests.exceptions.RequestException as e:
        raise e
    except ValueError as e:
        raise e
    except Exception as e:
        raise e

def retrieve_diaspora_host_meta(host):
    try:
        response = requests.get(f"{host}/.well-known/host-meta")
        response.raise_for_status()
        return XRD.from_xml(response.content)
    except requests.exceptions.RequestException as e:
        raise DiasporaHostMetaRetrievalError(f"Failed to retrieve host-meta document from {host}: {e}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except Exception as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of keys that will store the value
    :param keys: sub keys in the keys chain
    """
    # Check if the input dictionary is valid
    if not isinstance(dic, dict):
        raise ValueError("Invalid input dictionary")

    # Check if the key is valid
    if not isinstance(key, str):
        raise ValueError("Invalid key")

    # Check if the value is valid
    if not isinstance(val, (str, int, float)):
        raise ValueError("Invalid value")

    # Check if the keys are valid
    for k in keys:
        if not isinstance(k, str):
            raise ValueError("Invalid key")

    # Insert the value into the dictionary
    current_dict = dic
    for k in keys:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]
    current_dict[key] = val

    return dic

def list_of_file_names(settings_dirs, spec_option):
    """
    Returns a list of file names in the specified directory
    """
    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(spec_option):
                    file_names.append(os.path.join(root, file))
    return file_names

