def validate_from_content(spec_content):
    """
    Validates that the spec (YAML) content has all required fields.

    :param spec_content: Content of the spec file.
    :return: Dictionary with data loaded from the spec (YAML) file.
    """
    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing spec file: {e}")

    if not spec_data:
        raise IRValidatorException("Spec file is empty")

    if not spec_data.get("name"):
        raise IRValidatorException("'name' field is missing in spec file")

    if not spec_data.get("version"):
        raise IRValidatorException("'version' field is missing in spec file")

    if not spec_data.get("description"):
        raise IRValidatorException("'description' field is missing in spec file")

    if not spec_data.get("inputs"):
        raise IRValidatorException("'inputs' field is missing in spec file")

    if not spec_data.get("outputs"):
        raise IRValidatorException("'outputs' field is missing in spec file")

    if not spec_data.get("steps"):
        raise IRValidatorException("'steps' field is missing in spec file")

    return spec_data

def validate_from_file(yaml_file):
    """
    Loads and validates that a YAML file has all required fields.

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
            if not data:
                raise IRValidatorException("No data found in YAML file")
            if not data.get("name"):
                raise IRValidatorException("'name' field is missing in YAML file")
            if not data.get("version"):
                raise IRValidatorException("'version' field is missing in YAML file")
            if not data.get("description"):
                raise IRValidatorException("'description' field is missing in YAML file")
            if not data.get("license"):
                raise IRValidatorException("'license' field is missing in YAML file")
            if not data.get("authors"):
                raise IRValidatorException("'authors' field is missing in YAML file")
            if not data.get("requirements"):
                raise IRValidatorException("'requirements' field is missing in YAML file")
            if not data.get("entry_point"):
                raise IRValidatorException("'entry_point' field is missing in YAML file")
            if not data.get("tests"):
                raise IRValidatorException("'tests' field is missing in YAML file")
            if not data.get("dependencies"):
                raise IRValidatorException("'dependencies' field is missing in YAML file")
            if not data.get("dev_dependencies"):
                raise IRValidatorException("'dev_dependencies' field is missing in YAML file")
            return data
    except FileNotFoundError:
        raise IRValidatorException("YAML file not found")
    except yaml.YAMLError:
        raise IRValidatorException("Invalid YAML file")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of argument names and their default values.
    """
    # Initialize an empty dictionary to store the resolved defaults
    resolved_defaults = {}

    # Iterate over the arguments in the spec
    for arg_name, arg_spec in self.spec.items():
        # Check if the argument has a default value
        if 'default' in arg_spec:
            # If the argument has a default value, add it to the resolved defaults dictionary
            resolved_defaults[arg_name] = arg_spec['default']
        else:
            # If the argument does not have a default value, check if it has a default value in other sources
            if 'default_source' in arg_spec:
                # If the argument has a default value in other sources, add it to the resolved defaults dictionary
                resolved_defaults[arg_name] = self.get_default_from_source(arg_spec['default_source'])
            else:
                # If the argument does not have a default value in other sources, raise an exception
                raise ValueError(f"Argument '{arg_name}' does not have a default value and no default source was specified.")

    # Return the resolved defaults dictionary
    return resolved_defaults

