    """Returning dict with options which deprecate others. """
    return {
        "option1": ["option2", "option3"],
        "option4": ["option5", "option6"],
        "option7": ["option8", "option9"]
    }

def validate_arg_deprecation(cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if any of the arguments in the cli_args are deprecated
    for arg in cli_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{DEPRECATED_ARGS[arg]}' instead.")

    # Check if any of the arguments in the answer_file_args are deprecated
    for arg in answer_file_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{DEPRECATED_ARGS[arg]}' instead.")

    # If any of the arguments are deprecated, raise a ValueError
    if any(arg in DEPRECATED_ARGS for arg in cli_args) or any(arg in DEPRECATED_ARGS for arg in answer_file_args):
        raise ValueError("The arguments provided are deprecated and cannot be used.")

def _get_conditionally_required_args(command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if option["required_when"] and option["required_when"] in args:
            required_args.append(option["name"])
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > 10:
            raise ValueError("Argument value is too long")
    return args

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in self.available_choices:
            raise ValueError(f"Invalid choice: {arg}. Must be one of {self.available_choices}")
    return args

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < 0 or arg > 100:
            raise ValueError("Invalid argument value")
    return True

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is not None:
        for var in extra_vars:
            vars_dict[var] = True
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if key in self.arg_types[parser_name]:
            arg_type = self.arg_types[parser_name][key]
            if arg_type == "int":
                try:
                    values_dict[key] = int(value)
                except ValueError:
                    raise ValueError(f"Invalid value for argument {key}: {value}. Expected an integer.")
            elif arg_type == "float":
                try:
                    values_dict[key] = float(value)
                except ValueError:
                    raise ValueError(f"Invalid value for argument {key}: {value}. Expected a float.")
            elif arg_type == "bool":
                if value.lower() == "true":
                    values_dict[key] = True
                elif value.lower() == "false":
                    values_dict[key] = False
                else:
                    raise ValueError(f"Invalid value for argument {key}: {value}. Expected a boolean.")
            elif arg_type == "list":
                values_dict[key] = value.split(",")
            else:
                raise ValueError(f"Invalid argument type: {arg_type}.")
        else:
            raise ValueError(f"Invalid argument: {key}.")

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(plugin_dir / "plugin.json", "r") as f:
            plugin_spec = json.load(f)
    except FileNotFoundError:
        raise ValueError(f"Plugin spec file not found in {plugin_dir}")
    except json.JSONDecodeError:
        raise ValueError(f"Invalid JSON format in {plugin_dir}/plugin.json")

    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value

    return flatten_dict

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
